R,C=14,17
g=[[0]*C for _ in range(R)]
marks=[(3,6),(6,4),(8,1),(8,12),(10,10),(12,8)]
for r,c in marks:g[r][c]=2
# Horizontal backbone between markers in row 8
for c in range(2,12):g[8][c]=3
# Connect every other marker vertically to the backbone
for r,c in marks:
    if r<8:
        for rr in range(r+1,8):
            if g[rr][c]==0:g[rr][c]=3
